CREATE OR REPLACE FUNCTION private.phase3_agent_processing_action(p_order_id text, p_action text, p_reason text DEFAULT NULL::text, p_observation text DEFAULT NULL::text)
 RETURNS phase4_assignment_orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid text := nullif(btrim(coalesce((select auth.jwt()->>'sub'),'')), '');
  v_row public.phase4_assignment_orders;
  v_reason text := nullif(btrim(coalesce(p_reason,'')),'');
  v_observation text := nullif(btrim(coalesce(p_observation,'')),'');
begin
  if not public.is_izytel_firebase_jwt() or v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select * into v_row from public.phase4_assignment_orders where order_id=btrim(p_order_id) for update;
  if not found then raise exception 'ORDER_NOT_SYNCED'; end if;
  if v_row.assigned_agent_id is distinct from v_uid then raise exception 'ORDER_NOT_ASSIGNED_TO_AGENT' using errcode='42501'; end if;
  if v_row.assignment_state not in ('accepted','handed_off') then raise exception 'ORDER_NOT_ACCEPTED'; end if;
  if v_row.legacy_state_unresolved then raise exception 'LEGACY_STATUS_REQUIRES_RECONCILIATION'; end if;

  if p_action='start' then
    if v_row.order_status='inProgress' then return v_row; end if;
    if v_row.order_status<>'paidReady' then raise exception 'ORDER_NOT_READY'; end if;
    update public.phase4_assignment_orders
    set order_status='inProgress',processing_started_at=coalesce(processing_started_at,now()),updated_at=now()
    where order_id=v_row.order_id returning * into v_row;
  elsif p_action='hold' then
    if v_row.order_status<>'inProgress' then raise exception 'ORDER_NOT_IN_PROGRESS'; end if;
    if v_reason is null or char_length(v_reason)<3 or char_length(v_reason)>300 then raise exception 'INVALID_HOLD_REASON'; end if;
    update public.phase4_assignment_orders
    set order_status='onHold',last_hold_reason=v_reason,last_held_at=now(),updated_at=now()
    where order_id=v_row.order_id returning * into v_row;
  elsif p_action='resume' then
    if v_row.order_status<>'onHold' then raise exception 'ORDER_NOT_ON_HOLD'; end if;
    update public.phase4_assignment_orders
    set order_status='inProgress',last_resumed_at=now(),updated_at=now()
    where order_id=v_row.order_id returning * into v_row;
  elsif p_action='fail' then
    if v_row.order_status<>'inProgress' then raise exception 'ORDER_NOT_IN_PROGRESS'; end if;
    if v_reason is null or v_reason not in ('incorrectNumber','networkUnavailable','offerUnavailable','insufficientBalance','technicalError','incorrectPayment','other') then
      raise exception 'INVALID_FAILURE_REASON';
    end if;
    if v_observation is not null and char_length(v_observation)>1000 then raise exception 'INVALID_OBSERVATION'; end if;
    update public.phase4_assignment_orders
    set order_status='failed',completed_at=now(),failure_reason=v_reason,observation=v_observation,updated_at=now()
    where order_id=v_row.order_id returning * into v_row;
  else
    raise exception 'INVALID_PROCESSING_ACTION';
  end if;
  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION private.phase3_prepare_failed_order_for_reassignment(p_order_id text)
 RETURNS phase4_assignment_orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row public.phase4_assignment_orders;
begin
  if not private.is_izytel_finance_admin() then raise exception 'ADMIN_REQUIRED' using errcode='42501'; end if;
  select * into v_row from public.phase4_assignment_orders where order_id=btrim(p_order_id) for update;
  if not found then raise exception 'ORDER_NOT_SYNCED'; end if;
  if v_row.order_status<>'failed' then raise exception 'ORDER_NOT_FAILED'; end if;

  update public.phase4_assignment_history h
  set status='closed',updated_at=now()
  where h.id=(select h2.id from public.phase4_assignment_history h2
    where h2.order_id=v_row.order_id and h2.agent_id=v_row.assigned_agent_id
      and h2.status in ('assigned','accepted','handed_off')
    order by h2.assigned_at desc limit 1);

  update public.phase4_assignment_plans
  set candidate_agent_ids='{}'::text[],candidate_names='{}'::jsonb,refused_agent_ids='{}'::text[],plan_mode='manual',updated_at=now()
  where order_id=v_row.order_id;

  update public.phase4_assignment_orders
  set order_status='paidReady',processing_started_at=null,completed_at=null,failure_reason=null,observation=null,
      last_hold_reason=null,last_held_at=null,last_resumed_at=null,
      assignment_state='manual_required',assigned_agent_id=null,assigned_agent_name=null,assignment_mode=null,assigned_at=null,
      last_refusal_reason=null,last_refused_at=null,last_refused_agent_id=null,
      firebase_assignment_synced_at=null,firebase_handoff_at=null,legacy_state_unresolved=false,updated_at=now()
  where order_id=v_row.order_id returning * into v_row;
  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.phase4_import_legacy_refusals(p_order_id text, p_refused_agent_ids text[], p_manual_required boolean DEFAULT false)
 RETURNS phase4_assignment_orders
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_row public.phase4_assignment_orders;
  v_existing text[];
  v_merged text[];
begin
  if not private.is_izytel_phase4_staff() then raise exception 'STAFF_REQUIRED'; end if;

  select refused_agent_ids into v_existing
  from public.phase4_assignment_plans
  where order_id=p_order_id
  for update;
  if not found then raise exception 'ASSIGNMENT_PLAN_MISSING'; end if;

  select coalesce(array_agg(distinct x), '{}'::text[]) into v_merged
  from unnest(coalesce(v_existing,'{}'::text[]) || coalesce(p_refused_agent_ids,'{}'::text[])) as x
  where btrim(x) <> '';

  update public.phase4_assignment_plans
  set refused_agent_ids=v_merged, updated_at=now()
  where order_id=p_order_id;

  if p_manual_required then
    update public.phase4_assignment_orders
    set assignment_state='manual_required',
        assigned_agent_id=null,
        assigned_agent_name=null,
        assignment_mode=null,
        assigned_at=null,
        firebase_assignment_synced_at=null,
        firebase_handoff_at=null,
        updated_at=now()
    where order_id=p_order_id
      and assignment_state not in ('accepted','handed_off','closed')
    returning * into v_row;
  else
    select * into v_row from public.phase4_assignment_orders where order_id=p_order_id;
  end if;

  if v_row.order_id is null then raise exception 'ORDER_NOT_SYNCED'; end if;
  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.phase4_reconcile_acceptance(p_order_id text, p_firebase_handoff_confirmed boolean)
 RETURNS phase4_assignment_orders
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_row public.phase4_assignment_orders;
  v_history_id uuid;
begin
  if not private.is_izytel_phase4_staff() then
    raise exception 'STAFF_REQUIRED';
  end if;

  select * into v_row
  from public.phase4_assignment_orders
  where order_id = p_order_id
  for update;
  if not found then raise exception 'ORDER_NOT_SYNCED'; end if;

  if v_row.assignment_state <> 'accepted' then
    return v_row;
  end if;

  select h.id into v_history_id
  from public.phase4_assignment_history h
  where h.order_id = p_order_id
    and h.agent_id = v_row.assigned_agent_id
    and h.status = 'accepted'
  order by h.assigned_at desc
  limit 1;

  if p_firebase_handoff_confirmed then
    update public.phase4_assignment_orders
    set assignment_state = 'handed_off',
        firebase_assignment_synced_at = coalesce(firebase_assignment_synced_at, now()),
        firebase_handoff_at = coalesce(firebase_handoff_at, now()),
        updated_at = now()
    where order_id = p_order_id
    returning * into v_row;

    if v_history_id is not null then
      update public.phase4_assignment_history
      set status = 'handed_off', handed_off_at = coalesce(handed_off_at, now()),
          updated_at = now()
      where id = v_history_id;
    end if;
  else
    update public.phase4_assignment_orders
    set assignment_state = 'assigned',
        firebase_assignment_synced_at = null,
        firebase_handoff_at = null,
        updated_at = now()
    where order_id = p_order_id
    returning * into v_row;

    if v_history_id is not null then
      update public.phase4_assignment_history
      set status = 'assigned', accepted_at = null, handed_off_at = null,
          updated_at = now()
      where id = v_history_id;
    end if;
  end if;

  return v_row;
end;
$function$
